import heapq

def solve(grid, start, goal):
    if not grid or start == goal:
        if grid[start[0]][start[1]] == '.':
            return [start]
        else:
            return []

    rows, cols = len(grid), len(grid[0])
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    visited = set()
    heap = [(0, start[0], start[1], [start])]

    while heap:
        _, r, c, path = heapq.heappop(heap)
        if (r, c) == goal:
            return path
        if (r, c) in visited:
            continue
        visited.add((r, c))

        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in visited:
                new_path = path + [(nr, nc)]
                heapq.heappush(heap, (len(new_path) - 1, nr, nc, new_path))

    return []

