from heapq import heappush, heappop

def solve(grid, start, goal):
    if not grid or not start or not goal:
        return []
    rows, cols = len(grid), len(grid[0])
    start_row, start_col = start
    goal_row, goal_col = goal

    if grid[start_row][start_col] == '#' or grid[goal_row][goal_col] == '#':
        return []

    if start == goal:
        return [start]

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right

    def is_free(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def get_neighbors(r, c):
        neighbors = []
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_free(nr, nc):
                neighbors.append((nr, nc))
        return neighbors

    def jump_search(r, c, dir_r, dir_c, visited, path):
        path.append((r, c))
        while True:
            r += dir_r
            c += dir_c
            if not is_free(r, c):
                break
            if (r, c) not in visited:
                visited.add((r, c))
                path.append((r, c))
            else:
                break
        return path

    open_list = [(0, start)]
    came_from = {}
    visited = set()
    visited.add(start)
    path = [start]

    while open_list:
        _, current = heappop(open_list)
        r, c = current

        if current == goal:
            break

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_free(nr, nc) and (nr, nc) not in visited:
                visited.add((nr, nc))
                came_from[(nr, nc)] = current
                heappush(open_list, (1, (nr, nc)))

                # Jump in straight line
                path = [current]
                jump_path = jump_search(r, c, dr, dc, visited, path)
                for j in jump_path:
                    if j not in came_from:
                        came_from[j] = current
                        heappush(open_list, (len(path), j))

    if goal not in came_from:
        return []

    # Reconstruct path
    path = []
    current = goal
    while current != start:
        path.append(current)
        current = came_from[current]
    path.append(start)
